<script lang="ts">
  import {page} from '$app/state';
  import {goto} from '$app/navigation';
  import {tick} from 'svelte';
  import {ArrowLeft,ArrowRight,MagnifyingGlass,Stack,Info,ArrowUpRight} from 'phosphor-svelte';
  import {labContext} from '$lib/workspace/context';
  import {candidates,fromLive,promptForTurn,selectedPosition,validateWorkspaceTurn,type WorkspaceTurn} from '$lib/workspace/model';
  import {generationFor,generationLabel} from '$lib/pi/generation';
  import {answerWindows,firstStep2Recording,setupNames,type RecordingChoice} from '$lib/workspace/step2';
  const lab=labContext();
  let recorded=$state.raw<WorkspaceTurn|null>(null),loading=$state(false),error=$state('');
  let pos=$state<number|null>(null),channel=$state('answer'),wordsOnly=$state(true),search=$state('');
  let stream:HTMLDivElement|undefined=$state();
  let studyDetails:HTMLDetailsElement|undefined=$state();
  let catalog=$state.raw<RecordingChoice[]>([]),catalogError=$state('');
  const recordingId=$derived(page.url.searchParams.get('recording')??(page.url.searchParams.has('conversation')?'':'sietti-base'));
  const liveTurns=$derived(lab.live.pi?.turns??[]);
  const requestedTurn=$derived(page.url.searchParams.get('turn'));
  const liveTurn=$derived(requestedTurn?liveTurns.find(t=>t.request===requestedTurn):liveTurns.at(-1));
  const livePrompt=$derived(lab.live.pi&&liveTurn?promptForTurn(lab.live.pi,liveTurn):'');
  const turn=$derived(recordingId?recorded:liveTurn?fromLive(liveTurn,lab.live.labels??{},livePrompt):null);
  const study=$derived(turn?.step2);
  const step2Active=$derived(recordingId.startsWith('step2-'));
  const catalogSelection=$derived(catalog.find(r=>r.id===recordingId));
  const studyItems=$derived(catalog.filter((r,i)=>catalog.findIndex(x=>x.item===r.item)===i));
  const windows=$derived(turn&&study?answerWindows(turn.records,study):null);
  const registered=$derived(new Set(windows?.registered??[]));
  const rows=$derived(turn?.records.filter(r=>channel==='all'||r.channel===channel)??[]);
  const selected=$derived(turn?selectedPosition(turn,pos,channel):undefined);
  const selectedIndex=$derived(rows.findIndex(r=>r.pos===selected?.pos));
  const depths=$derived([...(turn?.layers??[])].sort((a,b)=>b-a));
  const matches=$derived(search.trim()?rows.filter(r=>(turn?.labels[r.token]??'').toLowerCase().includes(search.trim().toLowerCase())):[]);
  $effect(()=>{
    // Other Workspace sources do not depend on this external study being installed.
    if(!step2Active||catalog.length||catalogError)return;
    const abort=new AbortController();
    void fetch('/api/recordings',{signal:abort.signal}).then(async r=>{const d=await r.json();if(!r.ok)throw Error('Step 2 catalog unavailable. No recordings were substituted.');return d.step2 as RecordingChoice[];})
      .then(d=>{if(!abort.signal.aborted)catalog=d;}).catch(e=>{if(!abort.signal.aborted)catalogError=e.message;});
    return()=>abort.abort();
  });
  $effect(()=>{
    const id=recordingId;pos=null;error='';recorded=null;
    if(!id){loading=false;return;}
    const abort=new AbortController();loading=true;
    void fetch(`/api/recordings?id=${encodeURIComponent(id)}`,{signal:abort.signal}).then(async r=>{const data=await r.json();if(!r.ok)throw Error(data.error??'Recording unavailable.');return validateWorkspaceTurn(data);}).then(d=>{if(!abort.signal.aborted)recorded=d;}).catch(e=>{if(!abort.signal.aborted)error=e instanceof Error?e.message:'Recording unavailable.';}).finally(()=>{if(!abort.signal.aborted)loading=false;});
    return()=>abort.abort();
  });
  $effect(()=>{if(!recordingId){liveTurn?.request;pos=null;}});
  async function choose(position:number,focus=false){pos=position;await tick();const el=stream?.querySelector<HTMLButtonElement>(`[data-pos="${position}"]`);el?.scrollIntoView({block:'nearest'});if(focus)el?.focus();}
  function step(delta:number,focus=false){const r=rows[Math.max(0,Math.min(rows.length-1,selectedIndex+delta))];if(r)void choose(r.pos,focus);}
  function findNext(){const next=matches.find(r=>r.pos>(selected?.pos??-1))??matches[0];if(next)void choose(next.pos);}
  function changeChannel(value:string){channel=value;pos=null;search='';if(stream)stream.scrollTop=0;}
  function source(value:string){const id=value==='step2'?(catalog[0]?.id??firstStep2Recording):value;void goto(id==='live'?`/workspace?conversation=${lab.live.conversation??''}`:`/workspace?recording=${encodeURIComponent(id)}`);}
  function studyChoice(item:string,setup:string){const choice=catalog.find(r=>r.item===item&&r.setup===setup);if(choice)source(choice.id);}
  async function jumpAnswer(position:number|null|undefined){if(position==null)return;channel='answer';search='';await choose(position,true);}
  async function showStudyDetails(){if(studyDetails){studyDetails.open=true;await tick();studyDetails.scrollIntoView({block:'start'});studyDetails.querySelector('summary')?.focus();}}
</script>

<svelte:head><title>Global Workspace · Glimmer Lab</title><meta name="description" content="Select a recorded token and inspect every supplied workspace candidate across the captured lens depths."/></svelte:head>
<div class="workspace-page" class:study-page={step2Active}>
  <header class="workspace-heading"><div><span class="eyebrow">INSIDE THE RESPONSE</span><h1>Global Workspace</h1><p>Choose a token. See the words the lens surfaced at that exact position.</p></div><span class="record-label">{recordingId?'RECORDED CAPTURE':'SAVED PI READOUTS'}<span>No model call</span></span></header>
  <div class="workspace-source"><label>Source <select aria-label="Workspace source" value={step2Active?'step2':recordingId||'live'} onchange={e=>source(e.currentTarget.value)}><option value="step2">System-prompt study · 48 recordings</option><option value="sietti-base">Sietti paper · unsteered</option><option value="sietti-afraid">Sietti paper · afraid +0.5</option><option value="live" disabled={!lab.live.conversation}>Current conversation</option></select></label>
    {#if !recordingId}<label>Turn <select aria-label="Workspace turn" value={liveTurn?.request??''} onchange={e=>goto(`/workspace?conversation=${lab.live.conversation}&turn=${encodeURIComponent(e.currentTarget.value)}`)}>{#each liveTurns as t}<option value={t.request}>Turn {t.turn+1} · {t.status}</option>{/each}</select></label>{/if}
    {#if turn}<span>{turn.steering}</span><span class="source-layers">{turn.layers.length} lens depths · top {turn.k??'—'} each</span>{/if}
    {#if turn}<span data-testid="workspace-decoding">{study?`Sample ${study.sample} · T ${study.sampling.temperature.toFixed(1)} / p ${study.sampling.top_p} / k ${study.sampling.top_k}`:recordingId?'Decoding not recorded in this view':generationLabel(generationFor(lab.live.pi?.entries??[],liveTurn?.task,liveTurn?.request))}</span>{/if}
  </div>
  {#if step2Active&&catalogError}<p class="catalog-error" role="status">{catalogError}</p>{/if}
  {#if step2Active&&catalog.length}<div class="study-selectors">
    <label>Item <select aria-label="Study item" value={catalogSelection?.item??''} onchange={e=>studyChoice(e.currentTarget.value,catalogSelection?.setup??'default')}>{#each studyItems as item}<option value={item.item}>{item.entity}</option>{/each}</select></label>
    <label>Setup <select aria-label="Study setup" value={catalogSelection?.setup??''} onchange={e=>studyChoice(catalogSelection?.item??'',e.currentTarget.value)}>{#each Object.entries(setupNames) as [key,title]}<option value={key}>{title}</option>{/each}</select></label>
    <button onclick={showStudyDetails} disabled={!study}>Setup &amp; provenance ↓</button>
    <span>8 items × 6 setups · 1 Nov 2026</span>
  </div>{/if}
  {#if loading}<div class="workspace-empty" role="status"><Stack size={32}/><h2>Opening the recorded turn</h2><p>Checking the capture and tokenizer identities.</p></div>
  {:else if error}<div class="workspace-empty" role="alert"><Info size={28}/><h2>Recording unavailable</h2><p>{error}</p><a href="/">Back to chat →</a></div>
  {:else if !turn}<div class="workspace-empty"><Stack size={32}/><h2>No saved readout yet</h2><p>Enable workspace capture before sending a message, or open one of the recorded examples above.</p><a href="/">Back to chat →</a></div>
  {:else}
    <div class="workspace-question"><span>{study?'THE TASK':'THE PROMPT'}</span><p>{turn.prompt||'Prompt unavailable in this record.'}</p></div>
    {#if study}<div class="study-labels" aria-label="Classifier annotations">
      <span>Registered classifier <code>{study.classifier.registered}</code></span><span>Post-hoc C1+C2 sensitivity <code>{study.classifier.sensitivity}</code></span><span class="label-caveat">Classifier outputs, not truth badges</span>
      {#if study.classifier.warning}<p role="note" class="label-warning">{study.classifier.warning}</p>{/if}
    </div>{/if}
    <div class="workspace-grid">
      <section class="token-pane" aria-label="Recorded token stream">
        <header><div><h2>The response</h2><p>Click a token to hold its readout.</p></div><span>{rows.length.toLocaleString()} positions</span></header>
        <div class="channel-switch" aria-label="Readout channels">{#each [['answer','Answer'],['reasoning','Reasoning'],['all','All positions']] as [value,label]}<button aria-pressed={channel===value} onclick={()=>changeChannel(value)}>{label}</button>{/each}</div>
        {#if study&&windows}<div class="study-windows">
          <button class="registered-jump" onclick={()=>jumpAnswer(windows?.registered[0])}>Registered window · {windows.registered.length}/64 answer tokens</button>
          <button class="task-jump" onclick={()=>jumpAnswer(windows?.taskStart)}>Task response starts here →</button>
          <p>Supplemental jump: post hoc, not a decision time. Answer token index {study.marker.answerTokenIndex} (zero-based). The registered window stays unchanged.</p>
        </div>{/if}
        <form class="token-search" onsubmit={e=>{e.preventDefault();findNext();}}><MagnifyingGlass size={16}/><input aria-label="Find token text" bind:value={search} placeholder="Find a word in this stream…"/><button type="submit" disabled={!matches.length}>Find{search?` · ${matches.length}`:''}</button></form>
        <div class="token-stream" bind:this={stream}>
          {#if !rows.length}<p class="stream-empty">No {channel} positions were captured. Missing is not zero.</p>{/if}
          {#each rows as r (r.pos)}<button class="word-token" class:registered-token={registered.has(r.pos)} class:task-start={windows?.taskStart===r.pos} class:selected={r.pos===selected?.pos} class:template={r.channel==='template'||r.source==='prompt'} class:reasoning={r.channel==='reasoning'} class:unlabelled={turn.labels[r.token]==null} data-pos={r.pos} aria-label={`${turn.labels[r.token]??`Token #${r.token}`} · position ${r.pos}`} aria-pressed={r.pos===selected?.pos} tabindex={r.pos===selected?.pos?0:-1} title={`Consumed position ${r.pos} · token #${r.token} · ${r.channel??'prompt'}${registered.has(r.pos)?' · registered window':''}${windows?.taskStart===r.pos?' · supplemental task start (post hoc)':''}`} onclick={()=>choose(r.pos)} onkeydown={e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowLeft'?-1:1,true);}}}>{turn.labels[r.token]??`[#${r.token}]`}</button>{/each}
        </div>
        <footer><span>Token pieces · {channel==='all'?'all channels':channel}</span><div><button aria-label="Previous token" disabled={selectedIndex<=0} onclick={()=>step(-1)}><ArrowLeft size={17}/></button><span>{selectedIndex<0?'—':selectedIndex+1} / {rows.length}</span><button aria-label="Next token" disabled={selectedIndex<0||selectedIndex>=rows.length-1} onclick={()=>step(1)}><ArrowRight size={17}/></button></div></footer>
      </section>
      <section class="workspace-inspection" aria-label="Selected token workspace">
        <div class="selection-heading"><div><span class="eyebrow">SELECTED TOKEN</span><h2 data-testid="selected-token">{selected?(turn.labels[selected.token]?.trim()||`#${selected.token}`):'No position'}</h2><p>{selected?`Position ${selected.pos} · token #${selected.token} · ${selected.channel??'prompt'}`:'Choose a captured position.'}</p></div><span class="held-label">{pos===null?'START OF CHANNEL':'HELD FOR INSPECTION'}</span></div>
        <div class="depth-heading"><div><h3>Across the depths</h3><p>Deeper → shallower. Original ranks and raw lens scores.</p></div><label><input type="checkbox" bind:checked={wordsOnly}/>Word-like only</label></div>
        <p class="filter-note">{wordsOnly?'Special tokens and possible fragments are hidden, not discarded. Uncheck to see every supplied candidate.':'All supplied candidates are shown, including special tokens and fragments.'} Unknown labels stay visible as IDs.</p>
        {#if study}<p class="registered-ranks">Registered statistic: raw top 8, before the word-like filter. This view supplies top 16 and never renumbers ranks.{selected&&registered.has(selected.pos)?' Selected token is in the registered window.':''}</p>{/if}
        {#if !depths.length}<p class="workspace-missing">Workspace capture was off for this turn. A later setting cannot recover it.</p>{/if}
        <div class="depth-grid">{#each depths as layer}
          {@const raw=candidates(turn,selected,layer)}{@const shown=raw?.filter(c=>!wordsOnly||!c.hiddenReason)??[]}
          <article class="depth-card" aria-label={`Workspace layer ${layer}`}><header><span class="layer-mark">L{layer}</span><span>{raw?`${shown.length} of ${raw.length} shown`:'Not available'}</span>{#if raw&&wordsOnly&&shown.length<raw.length}<span class="hidden-count">{raw.length-shown.length} filtered</span>{/if}</header>
            {#if raw===null}<p class="workspace-missing">No workspace readout at this position. {selected?.missing.join(', ')||'No reason was supplied.'}</p>
            {:else if !shown.length}<p class="workspace-missing">No word-like candidates in the supplied top {raw.length}. Turn the filter off to inspect them.</p>
            {:else}<ol class="depth-candidates">{#each shown as c}<li value={c.rank}><span class="candidate-rank">{c.rank}</span><code title={`Token #${c.id}${c.hiddenReason?` · ${c.hiddenReason}`:''}`}>{c.label??`#${c.id} · unknown label`}</code><span class="candidate-score" title={`Raw score ${c.score}`}>{c.score.toFixed(2)}</span></li>{/each}</ol>{/if}
          </article>
        {/each}</div>
        <div class="unavailable-metrics"><div><h3>Broadcast</h3><span>Not measured</span><p>No calibrated ignition or broadcast statistic is supplied.</p></div><div><h3>Decidedness</h3><span>Not measured</span><p>No entropy or full-vocabulary confidence is supplied.</p></div></div>
        <p class="workspace-caveat"><Info size={15}/>Interpreted J-lens candidates after consuming this token. Not a thought transcript, probability, or proof of knowledge. Top-k is a partial vocabulary view; absence is not a zero score.</p>
        {#if study}<details class="study-provenance" bind:this={studyDetails}><summary>Setup, labels &amp; window provenance</summary>
          <h3>System text · {setupNames[study.setup]}</h3><pre>{study.system}</pre>
          <h3>Opener</h3><pre>{study.opener??'No opener.'}</pre>
          <p>{study.opener===null?'The task above is the user message, with no opener.':'The task shown above follows the opener in the same user message, separated by a blank line.'} No steering was applied.</p>
          <p>{study.classifier.provenance}</p>
          <h3>Supplemental task-response marker</h3><p>{study.marker.rule}. Selected by {study.marker.selectedBy}. Post hoc; not a decision time.</p>
          <p>Character offset {study.marker.charOffset} · answer token index {study.marker.answerTokenIndex} · {study.marker.answerTokens} captured answer tokens.</p>
          <blockquote>{study.marker.anchor}</blockquote>
          {#if study.marker.skipped.length}<h3>Skipped paragraph snippets</h3><ul>{#each study.marker.skipped as snippet}<li>{snippet}</li>{/each}</ul>{/if}
          <p>All windows remain accessible, including greeting-heavy openings. Neither the task marker nor a lens candidate establishes when a decision was made.</p>
          <p>Capture timestamp (as recorded): {study.capturedAt} · sample {study.sample} · seed {study.seed}.</p>
          <p>Captured directions <code>{study.assets.directions}</code><br/>Captured lens <code>{study.assets.lens}</code></p>
          <a href="/api/recordings?evidence=step2-precheck" target="_blank" rel="noopener">Separate precheck G1 evidence ↗</a>
          <p>One default scenario’s precheck, not 48 repeat tests. Main-run G3/G7 are not repeat checks.</p>
          <h3>Pinned inputs</h3><dl>{#each Object.entries(study.pins) as [file,pin]}<dt>{file}</dt><dd><code>{pin}</code></dd>{/each}</dl>
        </details>{/if}
        <details class="workspace-provenance"><summary>Source &amp; readout limits <ArrowUpRight size={14}/></summary><p>{turn.provenance.label}</p><p>{turn.provenance.schedule}</p><p>Labels are isolated decoded token pieces; partial Unicode may appear. All captured positions and supplied candidates remain accessible.</p>{#if turn.provenance.sha256}<p>Capture SHA-256 <code>{turn.provenance.sha256}</code></p>{/if}{#if turn.provenance.tokenizer}<p>Tokenizer SHA-256 <code>{turn.provenance.tokenizer}</code></p>{/if}<a href="/steering-diff">Compare baseline and steering →</a></details>
      </section>
    </div>
  {/if}
</div>

<style>
  .study-selectors{margin:0 28px;display:flex;align-items:center;gap:20px;padding:10px 0;border-bottom:1px solid var(--color-rule);flex-wrap:wrap;font-size:11px;color:var(--color-muted)}.study-selectors label{display:flex;align-items:center;gap:10px;min-width:0}.study-selectors select{max-width:400px;min-width:0;background:var(--color-paper-2);color:var(--color-ink);border:1px solid var(--color-rule);border-radius:6px;padding:8px;font-size:12px}.study-selectors>span{margin-left:auto;font:9px var(--font-mono)}
  .study-selectors>button{background:none;border:0;color:var(--color-accent);font-size:11px;padding:6px 0}
  .study-labels{display:flex;gap:10px 22px;flex-wrap:wrap;margin:0 28px 12px;font-size:10px;color:var(--color-muted)}.study-labels code{color:var(--color-ink);margin-left:5px;font-size:10px}.label-caveat{color:var(--color-faint)}.label-warning{flex-basis:100%;border-left:2px solid var(--color-accent);padding-left:10px;line-height:1.6}
  .study-windows{margin:0 28px 12px;display:flex;flex-direction:column;align-items:flex-start;gap:7px}.study-windows button{background:none;border:0;font-size:11px;text-align:left;color:var(--color-ink-2);padding:3px 0}.study-windows .registered-jump{border-bottom:2px solid var(--color-accent)}.study-windows .task-jump{border-left:2px dashed var(--color-muted);padding-left:8px}.study-windows p{font-size:10px;line-height:1.6;color:var(--color-muted)}.word-token.registered-token{background:color-mix(in oklch,var(--color-accent-soft) 55%,transparent)}.word-token.task-start{border-left:2px dashed var(--color-muted);padding-left:3px}.registered-ranks{font-size:10px;line-height:1.6;color:var(--color-muted);border-left:2px solid var(--color-accent);padding-left:9px;margin:0 0 14px}
  .study-provenance{margin-top:20px;border-top:1px solid var(--color-rule);padding-top:15px;color:var(--color-muted);font-size:11px;line-height:1.8}.study-provenance summary{cursor:pointer;color:var(--color-ink-2)}.study-provenance h3{font-size:11px;margin-top:16px}.study-provenance pre{font:11px/1.7 var(--font-mono);white-space:pre-wrap;margin-top:6px;color:var(--color-ink-2);overflow-wrap:anywhere}.study-provenance p{margin-top:12px;overflow-wrap:anywhere}.study-provenance code{font-size:10px;overflow-wrap:anywhere}.study-provenance a{color:var(--color-accent);display:inline-block;margin-top:14px}.study-provenance blockquote{margin:10px 0;border-left:2px solid var(--color-rule);padding-left:12px}.study-provenance ul{padding-left:18px}.study-provenance dt{margin-top:12px;overflow-wrap:anywhere}.study-provenance dd{margin:3px 0 0}.catalog-error{font-size:11px;color:var(--color-muted);padding:12px 28px}
  @media(max-width:820px){.study-selectors{margin-inline:24px;gap:10px}.study-selectors label{width:100%}.study-selectors select{max-width:calc(100vw - 100px);flex:1}.study-selectors>span{margin-left:0}.study-labels{margin-inline:24px}.study-windows{margin-inline:20px}.study-windows button{min-height:32px}}
