x var(--font-mono);color:var(--color-faint)}.channel-switch{display:flex;margin:0 28px 14px;border-bottom:1px solid var(--color-rule);gap:20px}.channel-switch button{background:none;border:0;border-bottom:2px solid transparent;color:var(--color-muted);font-size:12px;padding:10px 0}.channel-switch button[aria-pressed=true]{color:var(--color-ink);border-color:var(--color-accent)}.token-search{display:flex;align-items:center;margin:0 28px 16px;padding:8px 10px;border:1px solid var(--color-rule);border-radius:7px;color:var(--color-muted);gap:8px}.token-search input{width:100%;min-width:0;background:none;border:0;color:var(--color-ink);font-size:12px;outline-offset:2px}.token-search button{background:none;border:0;color:var(--color-muted);font-size:10px;padding:3px}.token-stream{flex:1;min-height:0;overflow:auto;padding:0 28px 28px;line-height:2.05;scrollbar-width:thin;scrollbar-color:var(--color-rule) transparent}.word-token{font:16px/2 Georgia,'Times New Roman',serif;white-space:pre-wrap;word-break:break-word;display:inline;border:0;border-radius:3px;background:transparent;padding:2px 0;color:var(--color-ink-2);text-align:left;transition:background 120ms}.word-token:hover{background:var(--color-paper-3)}.word-token.selected{background:var(--color-accent-soft);color:var(--color-accent);box-shadow:0 2px 0 var(--color-accent)}.word-token.reasoning{color:var(--color-muted);font-style:italic}.word-token.template{color:var(--color-faint);font:11px/2 var(--font-mono)}.word-token.unlabelled{font:11px var(--font-mono);border:1px dashed var(--color-rule)}.token-pane footer{border-top:1px solid var(--color-rule);padding:14px 28px;display:flex;align-items:center;justify-content:space-between;gap:12px;font:10px var(--font-mono);color:var(--color-muted)}.token-pane footer>div{display:flex;align-items:center;gap:10px}.token-pane footer button{display:flex;padding:5px;border:1px solid var(--color-rule);border-radius:5px;background:transparent}.workspace-inspection{min-height:0;overflo